def fibonacci():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

def evens_up_to(n):
    for i in range(n + 1):
        if i % 2 == 0:
            yield i

fib = fibonacci()
print("First 8 Fibonacci:")
for _ in range(8):
    print(next(fib), end=' ')

print("\n\nEvens up to 10:")
for e in evens_up_to(10):
    print(e, end=' ')
print()
